配置示例
示例 1 · 基本配置
functions
{
blendingFactor
{
type stabilityBlendingFactor;
libs (fieldFunctionObjects);
field U;
result UBlendingFactor;
tolerance 0.001;
switchNonOrtho yes;
maxNonOrthogonality 20;
minNonOrthogonality 60;
switchGradCc no;
maxGradCc 3;
minGradCc 4;
switchResiduals yes;
maxResidual 100;
P 5;
I 0.01;
D 0.5;
switchFaceWeight no;
minFaceWeight 0.3;
maxFaceWeight 0.2;
switchSkewness no;
maxSkewness 2;
minSkewness 3;
switchCo no;
Co1 1;
Co2 2;
writePrecision 10;
writeToFile false;
useUserTime true;
region region0;
enabled true;
log true;
timeStart 0;
timeEnd 1000;
executeControl timeStep;
