{
probes
{
type thermoCoupleProbes;
libs (utilityFunctionObjects);
writeControl timeStep;
writeInterval 1;
solver rodas23;
absTol 1e-12;
relTol 1e-8;
interpolationScheme cellPoint;
rho 8908;
Cp 440;
d 1e-3;
epsilon 0.5;
radiationField G;
probeLocations ((0.5 0.5 0.5));
fields (T);
}
}
