{
type surfaces;
libs (sampling);
writeControl writeTime;
surfaceFormat vtk;
fields (p U Q);
// interpolationScheme cellPoint; //<- default
surfaces
{
zNormal
{
type cuttingPlane;
point (0 0 0);
normal (0 0 1);
interpolate true;
}
isoQ
{
type isoSurface;
isoField Q;
isoValue 1000;
interpolate true;
}
propeller
{
type patch;
patches ("propeller.*");
interpolate true;
